def ones_run_is_strictly_longer(s):
    longest_zero = longest_one = 0
    current_zero = current_one = 0
    for char in s:
        if char == "1":
            current_one += 1
            current_zero = 0
            longest_one = max(longest_one, current_one)
        else:
            current_zero += 1
            current_one = 0
            longest_zero = max(longest_zero, current_zero)
    return longest_one > longest_zero

